const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];let data={stats:{},users:[],invoices:[],upgradeRequests:[],coupons:[],reports:[],pagination:{page:1,pages:1,total:0}},view='overview',userPage=1,userQuery='',searchTimer;const names={overview:['نظرة عامة','صورة مباشرة عن الحسابات والمبيعات واستخدام البوت.'],users:['المستخدمون','كل حساب وسيرفراته وبوتاته وحالته.'],subscriptions:['الاشتراكات','الخطط، الحالة، مدة الاشتراك والتعديل اليدوي.'],finance:['المبيعات والفواتير','الإيرادات والفواتير وطلبات الترقية.'],coupons:['الكوبونات','إنشاء العروض ومتابعة الاستخدام والانتهاء.'],reports:['البلاغات','متابعة الدعم والأولوية وحالة المعالجة.']};
const safe=v=>{const n=document.createElement('span');n.textContent=v??'—';return n.innerHTML},date=v=>v?new Date(v).toLocaleDateString('ar-SA'):'—',money=v=>`${(Number(v||0)/100).toLocaleString('ar-SA')} ر.س`;
async function csrf(){const r=await fetch('/api/csrf-token',{credentials:'include',cache:'no-store'});return(await r.json()).token}async function api(url,options={}){const method=String(options.method||'GET').toUpperCase(),headers={'Content-Type':'application/json',...(options.headers||{})};if(method!=='GET')headers['X-CSRF-Token']=await csrf();const r=await fetch(url,{...options,method,headers,credentials:'include',cache:'no-store'}),body=await r.json();if(!r.ok)throw new Error(body.error||'تعذر إكمال الطلب');return body}
function toast(t){const n=$('#toast');n.textContent=t;n.classList.remove('hidden');setTimeout(()=>n.classList.add('hidden'),2400)}function error(e){const n=$('#adminError');n.textContent=e.message;n.classList.remove('hidden')}
async function load(){
  const [{user},{stats},{users,pagination},{invoices,upgradeRequests},{coupons},{reports}]=await Promise.all([
    api('/api/me'),api('/api/admin/stats'),api(`/api/admin/users?page=${userPage}&q=${encodeURIComponent(userQuery)}`),
    api('/api/admin/finance'),api('/api/admin/coupons'),api('/api/admin/reports')
  ]);
  if(!user?.isAdmin)return location.replace('/admin-login');
  Object.assign(data,{stats,users,pagination,invoices,upgradeRequests,coupons,reports});
  $('#adminName').textContent=user.displayName||user.username;
  $('#avatar').src=user.avatar||'';
  $('#adminError').classList.add('hidden');render();
}
async function reloadUsers(keepFocus=false){
  const {users,pagination}=await api(`/api/admin/users?page=${userPage}&q=${encodeURIComponent(userQuery)}`);
  Object.assign(data,{users,pagination});render();
  if(keepFocus){const search=$('#search');search?.focus();search?.setSelectionRange(userQuery.length,userQuery.length)}
}
const card=(label,value,note='')=>`<article class="card metric"><span>${label}</span><b>${value}</b><small>${note}</small></article>`;function table(headers,rows,empty='لا توجد بيانات'){return `<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${headers.length}" class="empty">${empty}</td></tr>`}</tbody></table></div>`}
function overview(){const s=data.stats;return `<section class="cards admin-kpis">${card('إجمالي المستخدمين',s.users,`${s.active} نشط`)}${card('اشتراكات نشطة',s.active_subscriptions,`${s.expiring_soon} تنتهي خلال 7 أيام`)}${card('إيراد الشهر',money(s.revenue_month),`${s.paid_invoices} فاتورة مدفوعة`)}${card('السيرفرات المرتبطة',s.connected_servers,`${s.active_bots} بوت مفعل`)}${card('عمليات البوت',Number(s.bot_events||0).toLocaleString('ar-SA'),'إجمالي الأحداث المسجلة')}${card('مشاريع نشطة',s.projects,'مشاريع العملاء')}${card('بلاغات مفتوحة',s.open_reports,'تحتاج متابعة')}${card('كوبونات فعالة',s.active_coupons,'صالحة الآن')}</section><div class="admin-grid"><section class="panel"><div class="panel-head"><h2>توزيع الخطط</h2></div><div class="plan-bars">${['free','starter','growth','business'].map(k=>`<div><span>${k[0].toUpperCase()+k.slice(1)}</span><i><em style="width:${Math.round(Number(s[k]||0)/Math.max(1,Number(s.users))*100)}%"></em></i><b>${s[k]}</b></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>مؤشرات مالية</h2></div><div class="summary-list"><div><span>إجمالي الإيرادات</span><b>${money(s.revenue_total)}</b></div><div><span>إيراد الشهر</span><b>${money(s.revenue_month)}</b></div><div><span>طلبات ترقية</span><b>${data.upgradeRequests.filter(x=>x.status==='pending').length}</b></div></div></section></div>`}
function pager(){
  const p=data.pagination||{page:1,pages:1,total:data.users.length};
  if(p.pages<=1)return '';
  return `<div class="admin-pager"><button class="btn small admin-page" data-page="${p.page-1}" ${p.page<=1?'disabled':''}>السابق</button><span>صفحة ${p.page} من ${p.pages} · ${p.total} مستخدم</span><button class="btn small admin-page" data-page="${p.page+1}" ${p.page>=p.pages?'disabled':''}>التالي</button></div>`;
}
function usersView(){return `<section class="panel"><div class="panel-head"><h2>المستخدمون <span class="badge">${data.pagination?.total??data.users.length}</span></h2><input class="search" id="search" aria-label="ابحث عن مستخدم" placeholder="بحث بالاسم أو البريد" value="${safe(userQuery)}"></div><div id="userTable">${userTable(data.users)}</div>${pager()}</section>`}
function userTable(list){return table(['المستخدم','الخطة','الحالة','السيرفرات','البوتات','آخر دخول','إجراء'],list.map(u=>`<tr><td><b>${safe(u.displayName||u.username)}</b><small>${safe(u.email)}</small></td><td>${safe(u.plan)}</td><td>${safe(u.status)}</td><td>${u.serverCount}</td><td>${u.botCount}</td><td>${date(u.lastLoginAt)}</td><td><button class="btn small edit-user" data-id="${u.id}">تعديل</button></td></tr>`).join(''))}
function subscriptions(){return `<section class="panel">${table(['المستخدم','الخطة','الحالة','الدورة','الانتهاء','القيمة','إجراء'],data.users.map(u=>`<tr><td><b>${safe(u.displayName||u.username)}</b><small>${safe(u.email)}</small></td><td>${safe(u.plan)}</td><td>${safe(u.subscriptionStatus||'بدون اشتراك')}</td><td>${u.billingInterval==='annual'?'سنوي':'شهري'}</td><td>${date(u.currentPeriodEnd)}</td><td>${u.amountSar!=null?`${Number(u.amountSar).toLocaleString('ar-SA')} ر.س`:'—'}</td><td><button class="btn small edit-sub" data-id="${u.id}">إدارة</button></td></tr>`).join(''))}${pager()}</section>`}function finance(){return `<section class="cards">${card('إيراد الشهر',money(data.stats.revenue_month))}${card('الإيراد الكلي',money(data.stats.revenue_total))}${card('فواتير مدفوعة',data.stats.paid_invoices)}${card('طلبات ترقية',data.upgradeRequests.filter(x=>x.status==='pending').length)}</section><section class="panel"><div class="panel-head"><h2>آخر الفواتير</h2></div>${table(['العميل','المرجع','الحالة','المبلغ','الإصدار','الدفع'],data.invoices.map(i=>`<tr><td>${safe(i.display_name||i.username)}</td><td>${safe(i.provider_ref)}</td><td>${safe(i.status)}</td><td>${money(i.amount)}</td><td>${date(i.issued_at)}</td><td>${date(i.paid_at)}</td></tr>`).join(''))}</section><section class="panel"><div class="panel-head"><h2>طلبات الترقية</h2><small>السعر تقديري عند تقديم الطلب، ويعاد التحقق من الكوبون عند الدفع.</small></div>${table(['العميل','الخطة','الدورة','الكوبون','الإجمالي','الحالة','التاريخ'],data.upgradeRequests.map(r=>`<tr><td>${safe(r.display_name||r.username)}</td><td>${safe(r.plan)}</td><td>${r.billing_interval==='annual'?'سنوي':'شهري'}</td><td>${safe(r.coupon_code||'—')}</td><td>${r.total==null?'—':money(r.total)}</td><td>${safe(r.status)}</td><td>${date(r.created_at)}</td></tr>`).join(''))}</section>`}
function coupons(){return `<section class="panel"><div class="panel-head"><h2>الكوبونات</h2><button class="btn primary" id="newCoupon">＋ كوبون جديد</button></div>${table(['الرمز','الخصم','الاستخدام','الانتهاء','الحالة','إجراء'],data.coupons.map(c=>`<tr><td><b>${safe(c.code)}</b></td><td>${c.discount_type==='percent'?c.discount_value+'٪':money(c.discount_value)}</td><td>${c.redeemed_count} / ${c.max_redemptions||'∞'}</td><td>${date(c.expires_at)}</td><td>${c.active?'فعال':'متوقف'}</td><td><button class="btn small toggle-coupon" data-id="${c.id}" data-active="${c.active}">${c.active?'إيقاف':'تفعيل'}</button></td></tr>`).join(''))}</section>`}
function reports(){return `<section class="panel"><div class="panel-head"><h2>البلاغات</h2><span class="badge">${data.reports.length}</span></div>${table(['المرسل','الموضوع','التصنيف','الأولوية','الحالة','التاريخ'],data.reports.map(r=>`<tr data-report="${r.id}"><td>${safe(r.display_name||r.username||'زائر')}</td><td><b>${safe(r.subject)}</b><small>${safe(r.details).slice(0,80)}</small></td><td>${safe(r.category)}</td><td><select class="select report-priority"><option value="low" ${r.priority==='low'?'selected':''}>منخفض</option><option value="normal" ${r.priority==='normal'?'selected':''}>عادي</option><option value="high" ${r.priority==='high'?'selected':''}>مرتفع</option><option value="urgent" ${r.priority==='urgent'?'selected':''}>عاجل</option></select></td><td><select class="select report-status"><option value="open" ${r.status==='open'?'selected':''}>مفتوح</option><option value="in_progress" ${r.status==='in_progress'?'selected':''}>قيد المعالجة</option><option value="resolved" ${r.status==='resolved'?'selected':''}>تم الحل</option><option value="closed" ${r.status==='closed'?'selected':''}>مغلق</option></select></td><td>${date(r.created_at)}</td></tr>`).join(''))}</section>`}
function render(){const meta=names[view];$('#viewTitle').textContent=meta[0];$('#viewSubtitle').textContent=meta[1];$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#content').innerHTML=({overview,users:usersView,subscriptions,finance,coupons,reports}[view])();bind()}
function modal(html){$('#editorBody').innerHTML=html;$('#editor').showModal()}function bind(){
  const search=$('#search');
  if(search)search.oninput=event=>{userQuery=event.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{userPage=1;reloadUsers(true).catch(error)},350)};
  $$('.admin-page').forEach(button=>button.onclick=()=>{userPage=Number(button.dataset.page);reloadUsers().catch(error)});
  $$('.edit-user').forEach(b=>b.onclick=()=>{const u=data.users.find(x=>String(x.id)===b.dataset.id);modal(`<h2>تعديل المستخدم</h2><p>${safe(u.displayName||u.username)}</p><form id="userForm"><p>لتعديل الباقة استخدم قسم الاشتراكات.</p><label>الحالة<select name="status">${['active','suspended','cancelled'].map(x=>`<option ${u.status===x?'selected':''}>${x}</option>`).join('')}</select></label><button class="btn primary">حفظ التعديل</button></form>`);$('#userForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);await api(`/api/admin/users/${u.id}`,{method:'PATCH',body:JSON.stringify(Object.fromEntries(f))});$('#editor').close();await load();toast('تم تحديث المستخدم')}});$$('.edit-sub').forEach(b=>b.onclick=()=>{const u=data.users.find(x=>String(x.id)===b.dataset.id);const end=u.currentPeriodEnd?new Date(u.currentPeriodEnd).toISOString().slice(0,10):'';modal(`<h2>إدارة الاشتراك</h2><p>${safe(u.displayName||u.username)}</p><form id="subForm"><label>الخطة<select name="plan">${['free','starter','growth','business'].map(x=>`<option ${u.plan===x?'selected':''}>${x}</option>`).join('')}</select></label><label>الحالة<select name="status">${['trial','active','past_due','grace','cancelled','expired'].map(x=>`<option ${u.subscriptionStatus===x?'selected':''}>${x}</option>`).join('')}</select></label><label>الدورة<select name="billingInterval"><option value="monthly">شهري</option><option value="annual" ${u.billingInterval==='annual'?'selected':''}>سنوي</option></select></label><label>تاريخ الانتهاء<input name="currentPeriodEnd" type="date" value="${end}"></label><label>القيمة بالريال<input name="amountSar" type="number" min="0" value="${u.amountSar||0}"></label><button class="btn primary">حفظ الاشتراك</button></form>`);$('#subForm').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.currentTarget));await api(`/api/admin/users/${u.id}/subscription`,{method:'PUT',body:JSON.stringify(f)});$('#editor').close();await load();toast('تم تحديث الاشتراك')}});$('#newCoupon')?.addEventListener('click',()=>{modal(`<h2>كوبون جديد</h2><form id="couponForm"><label>الرمز<input name="code" required minlength="3"></label><label>نوع الخصم<select name="discountType"><option value="percent">نسبة مئوية</option><option value="fixed">مبلغ ثابت</option></select></label><label>قيمة الخصم (٪ للنسبة، ر.س للمبلغ الثابت)<input name="discountValue" type="number" min="1" required></label><label>أقصى استخدام<input name="maxRedemptions" type="number" min="1"></label><label>تاريخ الانتهاء<input name="expiresAt" type="date"></label><button class="btn primary">إنشاء الكوبون</button></form>`);$('#couponForm').onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.currentTarget));if(values.discountType==='fixed')values.discountValue=Number(values.discountValue)*100;await api('/api/admin/coupons',{method:'POST',body:JSON.stringify(values)});$('#editor').close();await load();toast('تم إنشاء الكوبون')}});$$('.toggle-coupon').forEach(b=>b.onclick=async()=>{await api(`/api/admin/coupons/${b.dataset.id}`,{method:'PATCH',body:JSON.stringify({active:b.dataset.active!=='true'})});await load();toast('تم تحديث الكوبون')});$$('[data-report]').forEach(row=>row.onchange=async()=>{await api(`/api/admin/reports/${row.dataset.report}`,{method:'PATCH',body:JSON.stringify({priority:row.querySelector('.report-priority').value,status:row.querySelector('.report-status').value})});toast('تم تحديث البلاغ')})}
$$('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});$('#refreshAdmin').onclick=()=>load().then(()=>toast('تم تحديث البيانات')).catch(error);$('#logout').onclick=async()=>{await api('/api/logout',{method:'POST'});location.replace('/')};load().catch(error);
